-- Paleta cálida (ADR 0017): los colores guardados pasan a sus equivalentes (no se borra nada; el resto queda igual).
UPDATE "space" SET "color" = CASE lower("color") when '#7c5cff' then '#A9471F' when '#22d3ee' then '#7A4E7E' when '#34d399' then '#4F7A52' when '#fbbf24' then '#B7791F' when '#f472b6' then '#B4637A' when '#60a5fa' then '#8C6A4F' when '#fb923c' then '#C2703D' when '#f43f5e' then '#A8321F' when '#8a93a6' then '#857B70' when '#a78bfa' then '#9C6B5A' ELSE "color" END WHERE lower("color") IN ('#7c5cff', '#22d3ee', '#34d399', '#fbbf24', '#f472b6', '#60a5fa', '#fb923c', '#f43f5e', '#8a93a6', '#a78bfa');--> statement-breakpoint
